#!/usr/bin/env bash
# A compact, cached map of this Next.js app: routes (URL → file, with route handlers and
# server actions), components with their exports, lib/ modules, hooks and stores. Read it
# instead of exploring with grep/ls: one read of a few hundred tokens replaces a dozen tool calls.
#   repo-map.sh            print the map (regenerated only when the tree changed)
#   repo-map.sh --refresh  force regeneration
# Generated by scripts, never by a model, so it costs nothing to keep current.
set -uo pipefail
ROOT="${CLAUDE_PROJECT_DIR:-$PWD}"
grep -qE '"next"[[:space:]]*:' "$ROOT/package.json" 2>/dev/null || { echo "(not a Next.js project)"; exit 0; }
CACHE="$ROOT/.claude/.cache/repo-map.md"; KEYF="$ROOT/.claude/.cache/repo-map.key"
mkdir -p "$ROOT/.claude/.cache"
APP=""; for d in app src/app; do [ -d "$ROOT/$d" ] && APP="$d"; done
SRC=""; [ -d "$ROOT/src" ] && SRC="src/"

PATHS=()
for p in "$APP" "${SRC}components" "${SRC}lib" "${SRC}hooks" "${SRC}stores" "${SRC}server"; do [ -n "$p" ] && [ -e "$ROOT/$p" ] && PATHS+=("$p"); done
[ "${#PATHS[@]}" -gt 0 ] || { echo "(no app/ or src/ directories found)"; exit 0; }
if git -C "$ROOT" rev-parse --is-inside-work-tree >/dev/null 2>&1; then
  KEY="$( { git -C "$ROOT" ls-files -s -- "${PATHS[@]}"; git -C "$ROOT" status --porcelain -uall -- "${PATHS[@]}"; } 2>/dev/null | cksum)"
else
  KEY="$(cd "$ROOT" && find "${PATHS[@]}" -type f -printf '%p %T@\n' 2>/dev/null | sort | cksum)"
fi
if [ "${1:-}" != --refresh ] && [ -s "$CACHE" ] && [ "$(cat "$KEYF" 2>/dev/null)" = "$KEY" ]; then cat "$CACHE"; exit 0; fi

exports() { # exports <file> -> exported names
  grep -oE '^export (default )?(async )?(function|const|class) [A-Za-z0-9_]+' "$1" 2>/dev/null | awk '{print $NF}' | tr '\n' ',' | sed 's/,$//'
}
{
  echo "# Repo map (generated $(date +%F) by repo-map.sh — regenerated automatically when files change)"
  echo
  if [ -n "$APP" ]; then
    echo "## Routes ($APP)"
    find "$ROOT/$APP" \( -name 'page.tsx' -o -name 'page.jsx' -o -name 'page.ts' -o -name 'route.ts' -o -name 'route.js' \) 2>/dev/null | sort | while IFS= read -r f; do
      r="${f#$ROOT/$APP}"; r="${r%/*}"
      url="$(printf '%s' "$r" | sed -E 's#/\([^)]*\)##g; s#/@[^/]+##g')"; [ -n "$url" ] || url="/"
      kind=page; case "$f" in */route.*) kind="route handler ($(grep -oE '^export (async )?function (GET|POST|PUT|PATCH|DELETE)' "$f" | awk '{print $NF}' | tr '\n' ' ' | sed 's/ $//'))" ;; esac
      extra=""; for s in loading error not-found layout; do ls "$(dirname "$f")/$s".* >/dev/null 2>&1 && extra="$extra $s"; done
      echo "- $url → ${f#$ROOT/} [$kind${extra:+;$extra}]"
    done | head -100
    echo
    SA="$(grep -rlE "^[[:space:]]*['\"]use server['\"]" "$ROOT/$APP" "$ROOT/${SRC}lib" "$ROOT/${SRC}server" 2>/dev/null | while IFS= read -r f; do printf '%s(%s) ' "${f#$ROOT/}" "$(exports "$f")"; done)"
    [ -n "$SA" ] && printf '## Server actions\n%s\n\n' "$SA"
  fi
  for d in "${SRC}components" "${SRC}lib" "${SRC}hooks" "${SRC}stores" "${SRC}server"; do
    [ -d "$ROOT/$d" ] || continue
    echo "## $d"
    find "$ROOT/$d" \( -name '*.ts' -o -name '*.tsx' \) -not -name '*.test.*' -not -name '*.spec.*' 2>/dev/null | sort | while IFS= read -r f; do
      e="$(exports "$f")"; c=""; head -3 "$f" | grep -qE "['\"]use client['\"]" && c=" [client]"
      echo "- ${f#$ROOT/$d/}${e:+: $e}$c"
    done | head -80
    echo
  done
} > "$CACHE.full" 2>/dev/null
# Trim after writing (piping into `head -c` would SIGPIPE the writer and, with pipefail, fail the
# whole step). The cap keeps the map a cheap read even on large apps.
head -c 6000 "$CACHE.full" > "$CACHE"; rm -f "$CACHE.full"
printf '%s' "$KEY" > "$KEYF"
cat "$CACHE"
